fn solve(input: Vec<char>) -> Vec<char> {
    // The input length is at least 18 and last char is '\n'.
    // Format: "AtCoder <Name> Contest\n"
    // Where <Name> starts with uppercase letter, followed by lowercase letters,
    // then a space, then "Contest", then '\n'.

    let prefix = ['A','t','C','o','d','e','r',' '];
    // Check prefix matches at start
    for (i, &p) in prefix.iter().enumerate() {
        if input[i] != p {
            // According to problem, input follows format,
            // but if needed, could handle error here.
            // We'll assume input is valid as described.
            // If invalid, could return empty or error.
            return Vec::new();
        }
    }

    // The name starts at index = length of prefix = 8
    // Name must start with uppercase letter
    let name_start = 8;
    let first_char = input[name_start];
    if !(first_char >= 'A' && first_char <= 'Z') {
        // Invalid name initial
        return Vec::new();
    }

    // Next characters of name are lowercase letters until next space
    // Find the next space after name_start
    let mut i = name_start + 1;
    while i < input.len() {
        if input[i] == ' ' {
            break;
        }
        // Must be lowercase letters
        if !(input[i] >= 'a' && input[i] <= 'z') {
            return Vec::new();
        }
        i += 1;
    }

    // i now points at the space after the name
    // The exact word "Contest" must come immediately after that space
    let contest_word = ['C','o','n','t','e','s','t'];
    let contest_start = i + 1;
    for (j, &c) in contest_word.iter().enumerate() {
        // check bounds safety
        if contest_start + j >= input.len() {
            return Vec::new();
        }
        if input[contest_start + j] != c {
            return Vec::new();
        }
    }

    // After "Contest" must be newline
    if contest_start + contest_word.len() != input.len() - 1 {
        return Vec::new();
    }
    if input[input.len() - 1] != '\n' {
        return Vec::new();
    }

    build_result(first_char)
}

fn build_result(ch: char) -> Vec<char> {
    // Returns "A<ch>C\n" as a char vector
    vec!['A', ch, 'C', '\n']
}